import java.util.*; public class ElectricityConnectionBilling { public static void main(String[]a){Scanner s=new Scanner(System.in);int n=s.nextInt();double t=0;while(n-->0){String x=s.next();double u=s.nextDouble(),b=x.equals("HOME")?(u<=100?5*u:500+7*(u-100)):x.equals("SHOP")?8*u+100:Math.max(1000,6*u);t+=b;System.out.printf("%s: %.2f%n",x,b);}System.out.printf("Total: %.2f%n",t);} }
